package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.neoforged.neoforge.client.event.*;import net.neoforged.bus.api.SubscribeEvent;import com.mojang.math.Axis;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class Pb01Client{
 public static net.minecraft.client.renderer.culling.Frustum frustum;private static BlockPos root;private static Direction face;private static Object world;private static String reason="";private static long checked;
 private static boolean update(){var m=Minecraft.getInstance();if(m.level==null||m.player==null||m.screen!=null||!(m.player.getMainHandItem().getItem()instanceof Pb01Item)||!(m.hitResult instanceof BlockHitResult hit)||hit.getType()!=HitResult.Type.BLOCK||hit.getDirection()!=Direction.UP){root=null;return false;}var context=new BlockPlaceContext(m.player,net.minecraft.world.InteractionHand.MAIN_HAND,m.player.getMainHandItem(),hit);var f=Pb01Item.face(m.player,m.player.getMainHandItem());var p=Pb01Item.anchor(context.getClickedPos(),f);if(world!=m.level||!p.equals(root)||f!=face||m.level.getGameTime()-checked>=5){world=m.level;root=p;face=f;checked=m.level.getGameTime();reason=Pb01Item.check(m.level,p,f,m.player,m.player.getMainHandItem());}return true;}
 @SubscribeEvent public static void preview(RenderLevelStageEvent e){frustum=e.getFrustum();if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS||!update())return;var m=Minecraft.getInstance();var c=e.getCamera().getPosition();var p=e.getPoseStack();var buffers=m.renderBuffers().bufferSource();var n=DefenseItem.data(m.player.getMainHandItem()).getCompound("BunkerState");p.pushPose();p.translate(root.getX()+.5-c.x,root.getY()-c.y,root.getZ()+.5-c.z);p.mulPose(Axis.YP.rotationDegrees(180-face.toYRot()));Pb01Model.get().draw(p,buffers,0xf000f0,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,n.getInt("Step")/21f,65535&~Pb01BlockEntity.broken(n),true,true,reason.isEmpty());p.popPose();buffers.endBatch();}
 @SubscribeEvent public static void hud(RenderGuiEvent.Post e){if(!update())return;var m=Minecraft.getInstance();e.getGuiGraphics().drawCenteredString(m.font,net.minecraft.network.chat.Component.translatable("pb01.preview",net.minecraft.network.chat.Component.translatable("defense.status."+(reason.isEmpty()?"CLEAR":reason))),m.getWindow().getGuiScaledWidth()/2,m.getWindow().getGuiScaledHeight()-66,reason.isEmpty()?0xff8ae2ac:0xffff8c85);}
}
